function UIViewPointEventDialog:Awake()
    local pars = self.controller.Argument.parameters   --界面传参
    self.point = pars.point
    self.eventType = self.point.type
    self.isViewMap = pars.isViewMap
    if not self.eventType then
        return
    end
    self.event = CfUtils.GetCfLine(AutoIds.IdSetting351, self.eventType)
    if not self.event then
        return
    end

    self:FillSelf()

    --如果是地图查看不显示路线和
    if self.isViewMap then
        KTool.SetActive(self.btnJump.gameObject, false)
    else
        self:FillWay()
        SetButtonAction(self.btnJump, Bind(self, self.OnBtnJump))
    end

    SetButtonAction(self.bg, Bind(self, self.OnBtnClose))
end

function UIViewPointEventDialog:FillSelf()
    --绘制共用的部分
    CfUtils.FillImage(self.eventImg, CfUtils.GetMazeViewIcon(self.point.type))
    CfUtils.FillImage(self.titlBgIma, CfUtils.GetMazeViewBg(self.point.type))

    CfUtils.FillText(self.titleText, CfUtils.GetCfDataByLine(self.event, Constants.Tab_MazePointType.name))
    CfUtils.FillText(self.content, CfUtils.GetCfDataByLine(self.event, Constants.Tab_MazePointType.eventDesc))
    local col   --color

    if checkNumber(self.eventType) == Constants.MazePointType.OrdinaryBattle or checkNumber(self.eventType) == Constants.MazePointType.CreamBattle
            or checkNumber(self.eventType) == Constants.MazePointType.BossBattle then
        --小怪战斗--精英战斗--boss
        self:FillBattle()
        if checkNumber(self.eventType) == Constants.MazePointType.BossBattle then
            self:FillBossTitle()
            --如果未激活了boos关卡
            if not MazeMgr:GetInstance():IsActiveBossPoint() then
                CfUtils.FillImage(self.eventImg, CfUtils.GetMazeViewIcon(Constants.MazePointType.UnKnown))
                CfUtils.FillImage(self.titlBgIma, CfUtils.GetMazeViewBg(Constants.MazePointType.UnKnown))
            end
        else
            self:FillPoint()
        end
    elseif checkNumber(self.eventType) == Constants.MazePointType.MysteriousShop or checkNumber(self.eventType) == Constants.MazePointType.CommonShop then
        --神秘商店--普通商店
        self:FillShop(self.eventType)
        self:FillPoint()
    elseif checkNumber(self.eventType) == Constants.MazePointType.Story then
        --剧情
        self:FillStory()
        self:FillPoint()
    elseif checkNumber(self.eventType) == Constants.MazePointType.JoinBattle then
        --助战
        self:FillJoin()
        self:FillPoint()
    else
        return
    end

    self.img.color = CfUtils.GetMazeCommonColor(self.point.type)
end

--非boss的时候显示关卡
function UIViewPointEventDialog:FillPoint()
    KTool.SetActive(self.point.gameObject, true)
    KTool.SetActive(self.title2.gameObject, false)

    CfUtils.FillText(self.curPointText, checkNumber(self.point.line) - 1 < 10 and "0" .. self.point.line - 1 or self.point.line - 1)
    CfUtils.FillText(self.allPointText, "/" .. MazeMapMgr:GetInstance():GetMaxLineNum())
end

--boss时候独特显示
function UIViewPointEventDialog:FillBossTitle()
    KTool.SetActive(self.point.gameObject, false)
    KTool.SetActive(self.title2.gameObject, true)
    CfUtils.FillCfText(self.curPointText, localize("最终战斗"))
end

--战斗事件
function UIViewPointEventDialog:FillBattle()
    CfUtils.FillCfText(self.cfText1, localize("武装值"))
    CfUtils.FillCfText(self.cfText2, localize("敌方情报"))
    CfUtils.FillCfText(self.cfText3, localize("奖励预览"))

    local questId = self.point.questId
    if questId then
        local enemysData = QuestConfMgr:GetInstance():GetEnemysDataInfo(questId)
        if enemysData then
            for i = 1, table.count(enemysData) do
                local go = self["CommonMonstCardNode" .. i]
                if go then
                    local data = enemysData[i]
                    KTool.SetActive(go, true)
                    local scr = CfUtils.GetLuaScr(go, CommonMonstCardNode)
                    if scr then
                        scr:RefeshInfo(data.id, nil, data.level, data.attr, data.grade)
                    end
                end
            end
        end

        local isNextPoint = MazeMapMgr:GetInstance():IsNextPoints(self.point)
        if isNextPoint then
            local monstPower = checkInt(MazeMgr:GetInstance():GetQuestEnumsPower(self.point))
            --不知道战斗力的时候隐藏
            KTool.SetActive(self.powerText, monstPower > 0)
            KTool.SetActive(self.cfText1, monstPower > 0)
            if monstPower > 0 then
                CfUtils.FillText(self.powerText, monstPower)
            end
        else
            KTool.SetActive(self.powerText, false)
            KTool.SetActive(self.cfText1, false)
        end

        local rewardData = RewardConfMgr:GetTeamShowRewardData(questId)
        local count = math.min(#rewardData, 3)

        local loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
        -- local prefabGo = loader:Instantiate()
        for i = 1, count do
            local go = self.rewards.transform:Find("item" .. i)
            if not go then
                go = loader:Instantiate(self.rewards.transform)
                go.name = "item" .. i
            end
            if go then
                CfUtils.RefeshGoodGo(go, rewardData[i].id, nil, 0.7)
            end
        end
        loader:Release()
    end

    KTool.SetActive(self.eventBattle, true)
end

--商店事件
function UIViewPointEventDialog:FillShop()
    CfUtils.FillCfText(self.cfText4, localize("使用货币："))
    if checkNumber(self.eventType) == Constants.MazePointType.MysteriousShop then
        self:RefreshItemNode(self.items, Constants.Currency.FreeDiamondId, nil, 0.5)
    elseif checkNumber(self.eventType) == Constants.MazePointType.CommonShop then
        self:RefreshItemNode(self.items, Constants.Currency.MazeCurrency, nil, 0.5)
    end

    KTool.SetActive(self.eventShop, true)
end

function UIViewPointEventDialog:FillWay()
    if MazeMapMgr:GetInstance():IsCurPoint(self.point) then
        return
    end

    local beginPos = MazeMapMgr:GetInstance():GetBuildActPos(MazeMapMgr:GetInstance().curPoint)
    local endPos = MazeMapMgr:GetInstance():GetBuildActPos(self.point)

    local b = CfUtils.GetBeizerList(beginPos, (beginPos + endPos) * 0.5 + Vector3(0, 10, 0), endPos, 20)
    for i = 1, #b - 1 do
        local go = CfUtils.InstantiateGo(self.wayIma, self.way)
        go.name = "way" .. i
        local pos = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(MazeMapMgr:GetInstance().mazeCam, b[#b - i])
        pos = CfUtils.ChangePosByCanvas(pos)
        go.transform.anchoredPosition = Vector3(pos.x, pos.y, 0)

        local rotation = Quaternion.New()
        if i + 1 <= #b then
            local pos1 = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(MazeMapMgr:GetInstance().mazeCam, b[#b - i + 1])
            pos1 = CfUtils.ChangePosByCanvas(pos1)
            if i > #b * 0.5 then
                rotation.eulerAngles = Vector3.New(CfUtils.AngleY(b[#b - i], b[#b - i + 1]), 0, -(180 + CfUtils.AngleY(pos1, pos)))
            else
                rotation.eulerAngles = Vector3.New(CfUtils.AngleY(b[#b - i], b[#b - i + 1]), 0, CfUtils.AngleY(pos1, pos))
            end
        end
        go.transform:GetComponent("RectTransform").localRotation = rotation    --角度
        KTool.SetActive(go, false)
    end

    self.co = cs_coroutine.start(self.CorWay, self)
end

--路线的动画
function UIViewPointEventDialog:CorWay()
    local cou = self.way.transform.childCount

    local i = 1
    while i < cou do
        local go = self.way.transform:Find("way" .. cou - i)
        if go then
            KTool.SetActive(go, true)
            coroutine.yield(WaitForSeconds(0.1))
        end
        i = i + 1
        if i >= cou then
            for i = 1, cou do
                local go = self.way.transform:Find("way" .. i)
                KTool.SetActive(go, false)
            end
            i = 1
            coroutine.yield(WaitForSeconds(0.5))
        end
    end
end

--剧情事件
function UIViewPointEventDialog:FillStory(eventType)
    local eventId = self.point.eventId

    if eventId then
        local storyCf = CfUtils.GetCfVo(AutoIds.IdSetting356, "MazeStoryVo", eventId)
