end

--助阵事件
function UIViewPointEventDialog:FillJoin()
    CfUtils.FillCfText(self.cfText6, localize("同事的身影"))
    CfUtils.FillCfText(self.cfText7, "")

    local assistants = self.point.assistants
    if assistants then
        for k, v in pairs(assistants) do
            local assistRole = CfUtils.GetCfVo(AutoIds.IdSetting361, "MazeAssistRoleVo", v.id)
            if assistRole then
                assistRole.isAssistant = Constants.MazeRole.AssistRole
                assistRole.cardLevel = checkNumber(v.cardLevel)
                assistRole.star = checkNumber(v.star)

                -- if not self._smallCardLoader then
                --     self._smallCardLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
                -- end
                -- if self._smallCardLoader.IsSuccess then
                    local go = self.heros.transform:Find("cell" .. k)
                    if not go then
                        CS.Engine.Modules.ResourceModule.LoadGameObjectAsync("Prefabs/Common/CommonSmallHeadNode.prefab", function (go)
                            go.name = "cell" .. k
                        end, true, self.heros.transform)
                    end
                    
                    if go then
                        CfUtils.RefeshCommonSmallHeroGo(go, assistRole, Vector3(0.7, 0.7, 1))
                    end
                -- end
            end
        end
    end
    KTool.SetActive(self.eventJoinBattle, true)
end

