function UIViewPointEventDialog:Update()
    if Utils.TouchCount() > 0 then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local uiList = CS.Engine.Tools.Utils.PointerOverUI(position)
            if uiList.Count < 1 then
                UIModule.CloseDialog(self.controller)
                --如果不是当前的点 视角归位
                if not MazeMapMgr:GetInstance():IsCurPoint(self.point) then
                    --MazePlayerMgr:GetInstance():RefeshPlayerRota(function()
                    Events.Broadcast(Constants.EventNames.MazeUpdataPreview)
                    --end, function()
                    MazeMgr:GetInstance():SetMazeMainUIActiveTrue()
                    --end)
                else
                    MazeMgr:GetInstance():SetMazeMainUIActiveTrue()
                end
                MazeMapMgr:GetInstance().viewPoint = nil
            end
        end
    end
end

