function UIViewPointEventDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.co then
            cs_coroutine.stop(self.co)
            self.co = nil
        end
        if not isNull(self._smallCardLoader) then
            self._smallCardLoader:Release()
            self._smallCardLoader = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

